  "notice.avoid": "Чтобы снизить риск непредвиденных ошибок, не используйте соответствующие функции во время загрузки матча, сохранения игры или отпуска тренера.",
  "notice.confirm": "Понятно",
  "notice.contact": "FMODD продолжает обновляться и совершенствоваться. Если вы обнаружили ошибку, хотите сообщить о проблеме, получить последнюю версию или присоединиться к обсуждению,",
  "notice.contact_end": ".",
  "notice.backup": "Обратите внимание: некоторые функции изменяют игровые данные и могут повредить сохранение или привести к потере данных. Перед использованием сделайте резервную копию сохранения.",
  "notice.dismiss": "Больше не показывать",
  "notice.free": "FMODD бесплатен. Если вам нравится инструмент, поддержать автора можно в настройках.",
  "notice.prohibited": "Любым лицам и организациям строго запрещено продавать этот инструмент, предлагать платные лицензии на него или включать его в платные комплекты.",
