  "notice.title": "Добро пожаловать в FMODD",
  "notice.versions": "Различия между версиями Football Manager могут привести к сбою некоторых функций или появлению непредвиденных данных.",
  "notice.warning": "Функции ставок и коэффициентов в этом инструменте предназначены исключительно для расширения игрового опыта Football Manager и не связаны с азартными играми или операциями с реальными деньгами. Строго запрещается использовать этот инструмент для любых азартных игр в реальном мире, незаконных ставок или иной противоправной деятельности.",
